// Jani × Eldama Secret Santa — single-endpoint n8n API
// Configure SECRET_SANTA_ADMIN_TOKEN in n8n, or replace ADMIN_TOKEN_FALLBACK below.
const ADMIN_TOKEN_FALLBACK = '';

const CONFIG = {
  STORE_KEY: 'jani_eldama_secret_santa_v1',
  ADMIN_TOKEN: (() => {
    try {
      const fromEnv = typeof $env !== 'undefined' && $env ? $env.SECRET_SANTA_ADMIN_TOKEN : '';
      return String(fromEnv || ADMIN_TOKEN_FALLBACK || '').trim();
    } catch (error) {
      return String(ADMIN_TOKEN_FALLBACK || '').trim();
    }
  })(),
  BUDGET: { currency: 'KES', minimum: 500, maximum: 1000 },
  MAX_DRAW_ATTEMPTS: 500,
};

let nodeCrypto = null;
try {
  nodeCrypto = require('crypto');
} catch (error) {
  nodeCrypto = null;
}

const webCrypto =
  typeof globalThis !== 'undefined' && globalThis.crypto ? globalThis.crypto : null;

class ApiError extends Error {
  constructor(statusCode, code, message) {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
  }
}

function fail(statusCode, code, message) {
  throw new ApiError(statusCode, code, message);
}

function nowIso() {
  return new Date().toISOString();
}

function randomBytes(length) {
  if (nodeCrypto && typeof nodeCrypto.randomBytes === 'function') {
    return Uint8Array.from(nodeCrypto.randomBytes(length));
  }
  if (webCrypto && typeof webCrypto.getRandomValues === 'function') {
    const bytes = new Uint8Array(length);
    webCrypto.getRandomValues(bytes);
    return bytes;
  }
  throw new Error('A secure random source is unavailable in this n8n environment.');
}

function randomInt(maxExclusive) {
  if (!Number.isInteger(maxExclusive) || maxExclusive <= 0) {
    throw new Error('randomInt requires a positive integer.');
  }
  if (nodeCrypto && typeof nodeCrypto.randomInt === 'function') {
    return nodeCrypto.randomInt(maxExclusive);
  }

  const range = 0x100000000;
  const limit = Math.floor(range / maxExclusive) * maxExclusive;
  const buffer = new Uint32Array(1);
  let value = 0;
  do {
    webCrypto.getRandomValues(buffer);
    value = buffer[0];
  } while (value >= limit);
  return value % maxExclusive;
}

function randomHex(byteLength) {
  return Array.from(randomBytes(byteLength), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

function randomToken() {
  return randomHex(32);
}

function randomId() {
  if (nodeCrypto && typeof nodeCrypto.randomUUID === 'function') {
    return nodeCrypto.randomUUID();
  }
  if (webCrypto && typeof webCrypto.randomUUID === 'function') {
    return webCrypto.randomUUID();
  }

  const bytes = randomBytes(16);
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
  return (
    hex.slice(0, 8) +
    '-' +
    hex.slice(8, 12) +
    '-' +
    hex.slice(12, 16) +
    '-' +
    hex.slice(16, 20) +
    '-' +
    hex.slice(20)
  );
}

function safelyEqual(left, right) {
  const a = String(left || '');
  const b = String(right || '');
  let difference = a.length ^ b.length;
  const length = Math.max(a.length, b.length);
  for (let index = 0; index < length; index += 1) {
    difference |= (a.charCodeAt(index) || 0) ^ (b.charCodeAt(index) || 0);
  }
  return difference === 0;
}

function shuffle(values) {
  const result = values.slice();
  for (let index = result.length - 1; index > 0; index -= 1) {
    const swapIndex = randomInt(index + 1);
    const temporary = result[index];
    result[index] = result[swapIndex];
    result[swapIndex] = temporary;
  }
  return result;
}

function getState() {
  const store = $getWorkflowStaticData('global');
  let state = store[CONFIG.STORE_KEY];

  if (!state || typeof state !== 'object' || Array.isArray(state)) {
    state = {
      version: 1,
      participants: [],
      assignments: [],
      draw_completed_at: null,
      created_at: nowIso(),
      updated_at: nowIso(),
    };
    store[CONFIG.STORE_KEY] = state;
  }

  if (!Array.isArray(state.participants)) state.participants = [];
  if (!Array.isArray(state.assignments)) state.assignments = [];
  if (typeof state.draw_completed_at !== 'string') state.draw_completed_at = null;
  if (typeof state.created_at !== 'string') state.created_at = nowIso();
  if (typeof state.updated_at !== 'string') state.updated_at = nowIso();

  return state;
}

function saveState(state) {
  state.updated_at = nowIso();
  $getWorkflowStaticData('global')[CONFIG.STORE_KEY] = state;
}

function getDrawStatus(state) {
  if (state.assignments.length > 0) return 'DRAW_COMPLETE';
  const activeCount = state.participants.filter((participant) => participant.participating).length;
  return activeCount >= 2 ? 'READY' : 'NOT_STARTED';
}

function getActiveParticipants(state) {
  return state.participants.filter((participant) => participant.participating);
}

function isEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function normalizeEmail(value) {
  return String(value || '').trim().toLowerCase();
}

function normalizeName(value) {
  return String(value || '').trim().replace(/\s+/g, ' ');
}

function normalizeCompany(value) {
  return String(value || '').trim();
}

function parseBoolean(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'boolean') return value;
  if (value === 1 || value === '1' || value === 'true') return true;
  if (value === 0 || value === '0' || value === 'false') return false;
  fail(400, 'VALIDATION_ERROR', 'Participation must be true or false.');
}

function validateParticipantFields(fields, options) {
  const partial = options && options.partial;
  const participant = {};

  if (!partial || Object.prototype.hasOwnProperty.call(fields, 'name')) {
    const name = normalizeName(fields.name);
    if (!name) fail(400, 'VALIDATION_ERROR', 'Participant name is required.');
    if (name.length > 100) {
      fail(400, 'VALIDATION_ERROR', 'Participant name must be 100 characters or fewer.');
    }
    participant.name = name;
  }

  if (!partial || Object.prototype.hasOwnProperty.call(fields, 'email')) {
    const email = normalizeEmail(fields.email);
    if (!email) fail(400, 'VALIDATION_ERROR', 'Email address is required.');
    if (!isEmail(email) || email.length > 254) {
      fail(400, 'VALIDATION_ERROR', 'Enter a valid email address.');
    }
    participant.email = email;
  }

  if (!partial || Object.prototype.hasOwnProperty.call(fields, 'company')) {
    const company = normalizeCompany(fields.company);
    if (company !== 'Jani' && company !== 'Eldama') {
      fail(400, 'VALIDATION_ERROR', 'Choose either Jani or Eldama.');
    }
    participant.company = company;
  }

  if (Object.prototype.hasOwnProperty.call(fields, 'participating')) {
    participant.participating = parseBoolean(fields.participating, true);
  } else if (!partial) {
    participant.participating = true;
  }

  return participant;
}

function findParticipantByToken(state, token) {
  if (!token) {
    fail(401, 'UNAUTHORIZED', "You don't have permission to perform this action.");
  }
  const participant = state.participants.find((candidate) =>
    safelyEqual(candidate.access_token || '', token),
  );
  if (!participant) {
    fail(404, 'PARTICIPANT_NOT_FOUND', "We couldn't find your Secret Santa profile.");
  }
  return participant;
}

function requireAdmin(token) {
  if (!CONFIG.ADMIN_TOKEN || CONFIG.ADMIN_TOKEN.length < 16) {
    fail(
      503,
      'ADMIN_NOT_CONFIGURED',
      'Admin access is not configured yet. Set SECRET_SANTA_ADMIN_TOKEN in n8n.',
    );
  }
  if (!safelyEqual(token, CONFIG.ADMIN_TOKEN)) {
    fail(401, 'UNAUTHORIZED', "You don't have permission to perform this action.");
  }
}

function findParticipantById(state, id) {
  const participant = state.participants.find((candidate) => candidate.id === String(id || ''));
  if (!participant) {
    fail(404, 'PARTICIPANT_NOT_FOUND', 'That participant could not be found.');
  }
  return participant;
}

function publicParticipant(participant) {
  return {
    id: participant.id,
    name: participant.name,
    email: participant.email,
    company: participant.company,
    participating: Boolean(participant.participating),
    assignment_revealed: Boolean(participant.assignment_revealed),
    created_at: participant.created_at,
  };
}

function assignmentStatus(state, participant) {
  if (!participant.participating) return 'Not participating';
  if (state.assignments.length === 0) return 'Pending draw';
  const assignment = state.assignments.find((item) => item.giver_id === participant.id);
  if (!assignment) return 'Missing';
  return participant.assignment_revealed ? 'Revealed' : 'Assigned';
}

function computeIntegrity(state) {
  const active = getActiveParticipants(state);
  const assignments = state.assignments;
  const applicable = assignments.length > 0 || Boolean(state.draw_completed_at);

  if (!applicable) {
    return {
      applicable: false,
      valid: false,
      checks: [],
      counts: {
        activeParticipants: active.length,
        assignments: 0,
        uniqueGivers: 0,
        uniqueRecipients: 0,
        selfAssignments: 0,
        missingGivers: active.length,
        inactiveIncluded: 0,
      },
    };
  }

  const activeIds = new Set(active.map((participant) => participant.id));
  const givers = assignments.map((assignment) => assignment.giver_id);
  const recipients = assignments.map((assignment) => assignment.recipient_id);
  const giverSet = new Set(givers);
  const recipientSet = new Set(recipients);
  const selfAssignments = assignments.filter(
    (assignment) => assignment.giver_id === assignment.recipient_id,
  ).length;
  const missingGivers = active.filter((participant) => !giverSet.has(participant.id)).length;
  const inactiveIncluded = assignments.filter(
    (assignment) =>
      !activeIds.has(assignment.giver_id) || !activeIds.has(assignment.recipient_id),
  ).length;
  const uniqueGivers = giverSet.size;
  const uniqueRecipients = recipientSet.size;
  const everyoneReceives =
    uniqueRecipients === active.length &&
    uniqueRecipients === assignments.length &&
    active.every((participant) => recipientSet.has(participant.id));

  const checks = [
    {
      id: 'no-self',
      label: 'No one is assigned to themselves',
      pass: selfAssignments === 0,
    },
    {
      id: 'everyone-gives',
      label: 'Every active participant has exactly one assignment',
      pass:
        assignments.length === active.length &&
        uniqueGivers === active.length &&
        missingGivers === 0 &&
        givers.length === uniqueGivers,
    },
    {
      id: 'everyone-receives',
      label: 'Every active participant receives exactly one gift',
      pass: everyoneReceives,
    },
    {
      id: 'no-duplicates',
      label: 'No recipient is assigned more than once',
      pass: recipients.length === uniqueRecipients,
    },
    {
      id: 'inactive-excluded',
      label: 'Inactive participants are excluded',
      pass: inactiveIncluded === 0,
    },
  ];

  return {
    applicable: true,
    valid: checks.every((check) => check.pass),
    checks,
    counts: {
      activeParticipants: active.length,
      assignments: assignments.length,
      uniqueGivers,
      uniqueRecipients,
      selfAssignments,
      missingGivers,
      inactiveIncluded,
    },
  };
}

function buildAdminState(state) {
  const active = getActiveParticipants(state);
  const participantById = new Map(
    state.participants.map((participant) => [participant.id, participant]),
  );

  const participants = state.participants
    .slice()
    .sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)))
    .map((participant) => ({
      ...publicParticipant(participant),
      invite_token: participant.access_token,
      assignment_status: assignmentStatus(state, participant),
    }));

  const assignments = state.assignments.map((assignment) => {
    const giver = participantById.get(assignment.giver_id);
    const recipient = participantById.get(assignment.recipient_id);
    return {
      id: assignment.id,
      giver_id: assignment.giver_id,
      recipient_id: assignment.recipient_id,
      giver: giver
        ? { id: giver.id, name: giver.name, company: giver.company }
        : { id: assignment.giver_id, name: 'Unknown participant', company: '' },
      recipient: recipient
        ? { id: recipient.id, name: recipient.name, company: recipient.company }
        : { id: assignment.recipient_id, name: 'Unknown participant', company: '' },
      status: giver && giver.assignment_revealed ? 'Revealed' : 'Not revealed',
      created_at: assignment.created_at,
    };
  });

  return {
    eventName: 'Jani × Eldama Secret Santa',
    budget: CONFIG.BUDGET,
    drawStatus: getDrawStatus(state),
    drawCompletedAt: state.draw_completed_at,
    participants,
    assignments,
    metrics: {
      totalParticipants: state.participants.length,
      activeParticipants: active.length,
      inactiveParticipants: state.participants.length - active.length,
      janiParticipants: active.filter((participant) => participant.company === 'Jani').length,
      eldamaParticipants: active.filter((participant) => participant.company === 'Eldama').length,
      assignmentsGenerated: state.assignments.length,
    },
    integrity: computeIntegrity(state),
  };
}

function createAssignmentSet(activeParticipants) {
  const ids = activeParticipants.map((participant) => participant.id);
  const createdAt = nowIso();

  for (let attempt = 0; attempt < CONFIG.MAX_DRAW_ATTEMPTS; attempt += 1) {
    const givers = shuffle(ids);
    const recipients = shuffle(ids);

    if (givers.some((giverId, index) => giverId === recipients[index])) {
      continue;
    }

    const assignments = givers.map((giverId, index) => ({
      id: randomId(),
      giver_id: giverId,
      recipient_id: recipients[index],
      created_at: createdAt,
    }));

    const giverSet = new Set(assignments.map((assignment) => assignment.giver_id));
    const recipientSet = new Set(assignments.map((assignment) => assignment.recipient_id));
    const valid =
      assignments.length === activeParticipants.length &&
      giverSet.size === activeParticipants.length &&
      recipientSet.size === activeParticipants.length &&
      assignments.every((assignment) => assignment.giver_id !== assignment.recipient_id) &&
      activeParticipants.every(
        (participant) => giverSet.has(participant.id) && recipientSet.has(participant.id),
      );

    if (valid) return assignments;
  }

  fail(
    500,
    'DRAW_FAILED',
    'The draw could not create a valid set of assignments. Please try again.',
  );
}

function readData(rawData) {
  if (rawData === undefined || rawData === null || rawData === '') return {};
  if (typeof rawData === 'object') {
    if (Array.isArray(rawData)) return {};
    return rawData;
  }
  try {
    const parsed = JSON.parse(String(rawData));
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (error) {
    fail(400, 'INVALID_REQUEST', 'The request payload was not valid JSON.');
  }
}

function readBody(input) {
  let body = input && input.body !== undefined ? input.body : {};
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      try {
        body = Object.fromEntries(new URLSearchParams(body));
      } catch (urlError) {
        body = {};
      }
    }
  }
  return body && typeof body === 'object' && !Array.isArray(body) ? body : {};
}

function readToken(input, body) {
  if (body && body.token) return String(body.token).trim();
  if (body && body.admin_token) return String(body.admin_token).trim();
  if (body && body.adminToken) return String(body.adminToken).trim();
  const headers = input && input.headers ? input.headers : {};
  const auth = headers.authorization || headers.Authorization || '';
  return String(auth).replace(/^Bearer\s+/i, '').trim();
}

function actionName(body) {
  return String(body.action || '').trim();
}

function route() {
  const input = $input.first().json || {};
  const body = readBody(input);
  const data = readData(body.data);
  const token = readToken(input, body);
  const action = actionName(body);
  const state = getState();

  if (!action) {
    fail(400, 'INVALID_REQUEST', 'An action is required.');
  }

  if (action === 'health') {
    return {
      ok: true,
      service: 'jani-eldama-secret-santa',
      adminConfigured: Boolean(CONFIG.ADMIN_TOKEN && CONFIG.ADMIN_TOKEN.length >= 16),
      drawStatus: getDrawStatus(state),
    };
  }

  if (action === 'me') {
    const participant = findParticipantByToken(state, token);
    const hasAssignment = state.assignments.some(
      (assignment) => assignment.giver_id === participant.id,
    );
    return {
      ok: true,
      participant: publicParticipant(participant),
      drawStatus: getDrawStatus(state),
      hasAssignment,
      budget: CONFIG.BUDGET,
      drawCompletedAt: state.draw_completed_at,
    };
  }

  if (action === 'my_assignment') {
    const participant = findParticipantByToken(state, token);
    if (state.assignments.length === 0) {
      fail(409, 'DRAW_NOT_COMPLETE', "The Secret Santa draw hasn't been completed yet.");
    }

    const assignment = state.assignments.find(
      (candidate) => candidate.giver_id === participant.id,
    );
    if (!assignment) {
      fail(
        409,
        'ASSIGNMENT_NOT_FOUND',
        'Your assignment is missing. Please contact the event organizer.',
      );
    }

    const recipient = state.participants.find(
      (candidate) => candidate.id === assignment.recipient_id,
    );
    if (!recipient) {
      fail(
        500,
        'ASSIGNMENT_ERROR',
        'Your assignment could not be loaded. Please contact the event organizer.',
      );
    }

    if (!participant.assignment_revealed) {
      participant.assignment_revealed = true;
      saveState(state);
    }

    return {
      ok: true,
      assignment: {
        recipient: {
          name: recipient.name,
          company: recipient.company,
        },
        budget: CONFIG.BUDGET,
      },
    };
  }

  if (action === 'admin_state' || action === 'admin_login') {
    requireAdmin(token);
    return { ok: true, admin: buildAdminState(state) };
  }

  if (action === 'admin_participants') {
    requireAdmin(token);
    const admin = buildAdminState(state);
    return { ok: true, participants: admin.participants, metrics: admin.metrics };
  }

  if (action === 'admin_assignments') {
    requireAdmin(token);
    const admin = buildAdminState(state);
    return {
      ok: true,
      assignments: admin.assignments,
      integrity: admin.integrity,
      drawStatus: admin.drawStatus,
    };
  }

  if (action === 'admin_create_participant') {
    requireAdmin(token);
    if (state.assignments.length > 0) {
      fail(409, 'ALREADY_DRAWN', 'Reset the draw before changing participants.');
    }

    const fields = validateParticipantFields(data, { partial: false });
    const duplicate = state.participants.some(
      (participant) => participant.email === fields.email,
    );
    if (duplicate) {
      fail(409, 'EMAIL_IN_USE', 'That email address is already registered.');
    }

    const participant = {
      id: randomId(),
      name: fields.name,
      email: fields.email,
      company: fields.company,
      participating: fields.participating,
      assignment_revealed: false,
      access_token: randomToken(),
      created_at: nowIso(),
      updated_at: nowIso(),
    };

    state.participants.push(participant);
    saveState(state);
    return {
      ok: true,
      participant: {
        ...publicParticipant(participant),
        invite_token: participant.access_token,
      },
      admin: buildAdminState(state),
    };
  }

  if (action === 'admin_update_participant') {
    requireAdmin(token);
    if (state.assignments.length > 0) {
      fail(409, 'ALREADY_DRAWN', 'Reset the draw before changing participants.');
    }

    const participant = findParticipantById(state, data.id);
    const fields = validateParticipantFields(data, { partial: true });

    if (fields.email && fields.email !== participant.email) {
      const duplicate = state.participants.some(
        (candidate) =>
          candidate.id !== participant.id && candidate.email === fields.email,
      );
      if (duplicate) {
        fail(409, 'EMAIL_IN_USE', 'That email address is already registered.');
      }
    }

    Object.assign(participant, fields, { updated_at: nowIso() });
    saveState(state);
    return { ok: true, admin: buildAdminState(state) };
  }

  if (action === 'admin_delete_participant') {
    requireAdmin(token);
    if (state.assignments.length > 0) {
      fail(409, 'ALREADY_DRAWN', 'Reset the draw before changing participants.');
    }

    const participant = findParticipantById(state, data.id);
    state.participants = state.participants.filter(
      (candidate) => candidate.id !== participant.id,
    );
    saveState(state);
    return { ok: true, admin: buildAdminState(state) };
  }

  if (action === 'admin_regenerate_token') {
    requireAdmin(token);
    const participant = findParticipantById(state, data.id);
    participant.access_token = randomToken();
    participant.updated_at = nowIso();
    saveState(state);
    return {
      ok: true,
      participant: {
        ...publicParticipant(participant),
        invite_token: participant.access_token,
      },
      admin: buildAdminState(state),
    };
  }

  if (action === 'admin_run_draw') {
    requireAdmin(token);
    if (state.assignments.length > 0) {
      fail(409, 'ALREADY_DRAWN', 'The Secret Santa draw has already been completed.');
    }

    const active = getActiveParticipants(state);
    if (active.length < 2) {
      fail(400, 'INSUFFICIENT_PARTICIPANTS', 'At least two participants are required.');
    }

    const emails = new Set();
    active.forEach((participant) => {
      if (!participant.name) {
        fail(400, 'VALIDATION_ERROR', 'Every participant must have a name.');
      }
      if (!isEmail(participant.email || '')) {
        fail(400, 'VALIDATION_ERROR', 'Every participant must have a valid email address.');
      }
      if (participant.company !== 'Jani' && participant.company !== 'Eldama') {
        fail(400, 'VALIDATION_ERROR', 'Every participant must belong to Jani or Eldama.');
      }
      if (emails.has(participant.email)) {
        fail(400, 'VALIDATION_ERROR', 'Every participant must have a unique email address.');
      }
      emails.add(participant.email);
    });

    const assignments = createAssignmentSet(active);
    state.assignments = assignments;
    state.draw_completed_at = nowIso();
    state.participants.forEach((participant) => {
      participant.assignment_revealed = false;
    });
    saveState(state);
    return { ok: true, admin: buildAdminState(state) };
  }

  if (action === 'admin_reset_draw') {
    requireAdmin(token);
    state.assignments = [];
    state.draw_completed_at = null;
    state.participants.forEach((participant) => {
      participant.assignment_revealed = false;
    });
    saveState(state);
    return { ok: true, admin: buildAdminState(state) };
  }

  fail(404, 'NOT_FOUND', 'That API action does not exist.');
}

let response;
try {
  response = { statusCode: 200, body: route() };
} catch (error) {
  if (error instanceof ApiError) {
    response = {
      statusCode: error.statusCode,
      body: { ok: false, error: { code: error.code, message: error.message } },
    };
  } else {
    response = {
      statusCode: 500,
      body: {
        ok: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'Something went wrong in the Secret Santa backend.',
        },
      },
    };
  }
}

return [{ json: response }];
